o htmlspecialchars($message);?></div><?php endif;?><form method="post"><div class="form-grid"><div class="field"><label>Şehir</label><select id="city-list"><option value="">Şehir seçin</option><?php foreach($cities as $city):?><option value="<?php echo htmlspecialchars($city);?>"><?php echo htmlspecialchars($city);?></option><?php endforeach;?></select></div><div class="field"><label>Klinik</label><select name="clinic" id="clinic-list" required><option value="">Önce şehir seçin</option></select></div><div class="field field-full"><label>Doktor</label><select name="doctor" id="doctor-list" required><option value="">Önce şehir seçin</option></select></div><div class="field field-full"><label>Çalışma günleri</label><div class="days"><?php foreach(['Monday'=>'Pazartesi','Tuesday'=>'Salı','Wednesday'=>'Çarşamba','Thursday'=>'Perşembe','Friday'=>'Cuma','Saturday'=>'Cumartesi'] as $value=>$label):?><label class="day"><input type="checkbox" value="<?php echo $value;?>" name="daylist[]"> <?php echo $label;?></label><?php endforeach;?></div></div><div class="field"><label>Başlangıç</label><input type="time" name="starttime" required></div><div class="field"><label>Bitiş</label><input type="time" name="endtime" required></div></div><div class="form-actions"><a class="button secondary" href="mainpage.php">İptal</a><button class="button" type="submit" name="Submit">Atamayı Kaydet</button></div></form></section></main><script src="jquerypart.js"></script><script>function load(url,data,target){fetch(url,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(data)}).then(r=>r.text()).then(html=>document.getElementById(target).innerHTML=html).catch(()=>document.getElementById(target).innerHTML='<option value="">Liste yüklenemedi</option>')}document.getElementById('city-list').addEventListener('change',function(){load('getclinic.php',{city:this.value},'clinic-list');load('getdoctorregion.php',{city:this.value},'doctor-list')});</script></